    &self,
    query: SearchQuery,
    semantics: RetrievalSemantics,
    defer_recording: bool,
    parent: Option<&crate::storage::work::WorkTicket>,
) -> Result<SemanticsResponse> {
    let work = self.accept_work(parent)?;
    let result = async {
        let stamp = self.meta_store.effects_stamp().await?;
